from dataclasses import dataclass, field

import requests
import structlog

log = structlog.get_logger()

LEDGER_URL = "https://ledger.internal.acme.example/v1/postings"


@dataclass
class Invoice:
    id: str
    customer_id: str
    subtotal_cents: int
    tax_cents: int = 0
    ledger_ref: str | None = None
    lines: list = field(default_factory=list)


def finalize(invoice):
    payload = {"invoice": invoice.id, "amount": invoice.subtotal_cents + invoice.tax_cents}
    # The ledger deduplicates on invoice id, so retrying a post is safe.
    for attempt in range(1, FINALIZE_MAX_ATTEMPTS + 1):
        try:
            resp = requests.post(LEDGER_URL, json=payload, timeout=10)
            resp.raise_for_status()
            break
        except requests.RequestException:
            if attempt == FINALIZE_MAX_ATTEMPTS:
                raise
            log.warning("invoice_finalize_retry", invoice_id=invoice.id, attempt=attempt)
    invoice.ledger_ref = resp.json()["ref"]
    log.info("invoice_finalized", invoice_id=invoice.id)
    return invoice


def finalize_once(invoice):
    if invoice.ledger_ref:
        return invoice
    return finalize(invoice)
